package checks

import (
	"fmt"
	"sort"

	"github.com/fclairamb/solidping/server/internal/checkers/checkerdef"
	"github.com/fclairamb/solidping/server/internal/secretref"
)

// validateVarRefs reports every unknown `${var:…}` name in a config, nested
// maps and slices included, one error per occurrence, in key order. A known
// name never fails here: it is generated by the executing process on each run.
//
// It is pure, so the write paths, `validate_check` (both through
// configValidationErrors) and the offline document validator share it.
func validateVarRefs(config map[string]any) []error {
	type found struct{ key, name string }

	var hits []found

	secretref.VisitStrings(config, func(key, value string) {
		for _, name := range secretref.UnknownVarRefs(value) {
			hits = append(hits, found{key: key, name: name})
		}
	})

	sort.SliceStable(hits, func(i, j int) bool { return hits[i].key < hits[j].key })

	errs := make([]error, 0, len(hits))
	for i := range hits {
		hit := &hits[i]
		// No Parameter: the finding lands on `config`, and the message names
		// the key itself.
		errs = append(errs, checkerdef.NewConfigError("",
			fmt.Sprintf("config.%s: %s", hit.key, secretref.UnknownVarMessage(hit.name))))
	}

	return errs
}
